#ifndef MRUBY_COMPILE_H
#define MRUBY_COMPILE_H

#include "common.h"

/**
 * MRuby Compiler
 */
MRB_BEGIN_DECL

#include <mruby.h>

struct mrb_parser_state;
/* load context */
typedef struct mrbc_context {
  mrb_sym *syms;
  int slen;
  char *filename;
  uint16_t lineno;
  int (*partial_hook)(struct mrb_parser_state*);
  void *partial_data;
  struct RClass *target_class;
  mrb_bool capture_errors:1;
  mrb_bool dump_result:1;
  mrb_bool no_exec:1;
  mrb_bool keep_lv:1;
  mrb_bool no_optimize:1;
  mrb_bool no_ext_ops:1;
  const struct RProc *upper;

  size_t parser_nerr;
} mrbc_context;

MRB_API mrbc_context* mrbc_context_new(mrb_state *mrb);
MRB_API void mrbc_context_free(mrb_state *mrb, mrbc_context *cxt);
MRB_API const char *mrbc_filename(mrb_state *mrb, mrbc_context *c, const char *s);
MRB_API void mrbc_partial_hook(mrb_state *mrb, mrbc_context *c, int (*partial_hook)(struct mrb_parser_state*), void*data);
MRB_API void mrbc_cleanup_local_variables(mrb_state *mrb, mrbc_context *c);

/* AST node structure */
typedef struct mrb_ast_node {
  struct mrb_ast_node *car, *cdr;
  uint16_t lineno, filename_index;
} mrb_ast_node;

/* lexer states */
enum mrb_lex_state_enum {
  EXPR_BEG,                   /* ignore newline, +/- is a sign. */
  EXPR_END,                   /* newline significant, +/- is an operator. */
  EXPR_ENDARG,                /* ditto, and unbound braces. */
  EXPR_ENDFN,                 /* ditto, and unbound braces. */
  EXPR_ARG,                   /* newline significant, +/- is an operator. */
  EXPR_CMDARG,                /* newline significant, +/- is an operator. */
  EXPR_MID,                   /* newline significant, +/- is a sign. */
  EXPR_FNAME,                 /* ignore newline, no reserved words. */
  EXPR_DOT,                   /* right after '.' or '::', no reserved words. */
  EXPR_CLASS,                 /* immediate after 'class', no here document. */
  EXPR_VALUE,                 /* alike EXPR_BEG but label is disallowed. */
  EXPR_MAX_STATE
};

/* saved error message */
struct mrb_parser_message {
  uint16_t lineno;
  int column;
  char* message;
};

#define STR_FUNC_PARSING 0x01
#define STR_FUNC_EXPAND  0x02
#define STR_FUNC_REGEXP  0x04
#define STR_FUNC_WORD    0x08
#define STR_FUNC_SYMBOL  0x10
#define STR_FUNC_ARRAY   0x20
#define STR_FUNC_HEREDOC 0x40
#define STR_FUNC_XQUOTE  0x80

enum mrb_string_type {
  str_not_parsing  = (0),
  str_squote   = (STR_FUNC_PARSING),
  str_dquote   = (STR_FUNC_PARSING|STR_FUNC_EXPAND),
  str_regexp   = (STR_FUNC_PARSING|STR_FUNC_REGEXP|STR_FUNC_EXPAND),
  str_sword    = (STR_FUNC_PARSING|STR_FUNC_WORD|STR_FUNC_ARRAY),
  str_dword    = (STR_FUNC_PARSING|STR_FUNC_WORD|STR_FUNC_ARRAY|STR_FUNC_EXPAND),
   169  static mrb_value
   170  f_instance_eval(mrb_state *mrb, mrb_value self)
   171  {
   172    if (!mrb_block_given_p(mrb)) {
   173      const char *s;
   174      mrb_int len;
   175      const char *file = NULL;
   176      mrb_int line = 1;
   177      struct RClass *c;
   178      struct RProc *proc;
   179
   180      mrb_get_args(mrb, "s|zi", &s, &len, &file, &line);
   181      c = mrb_singleton_class_ptr(mrb, self);
   182      proc = create_proc_from_string(mrb, s, len, mrb_nil_value(), file, line);
   183      MRB_PROC_SET_TARGET_CLASS(proc, c);
   184      mrb_assert(!MRB_PROC_CFUNC_P(proc));
   185      mrb_vm_ci_target_class_set(mrb->c->ci, c);
   186      return exec_irep(mrb, self, proc);
   187    }
   188    else {
   189      mrb_get_args(mrb, "");
   190      return mrb_obj_instance_eval(mrb, self);
   191    }
   192  }
   193
   194  static mrb_value
   195  f_class_eval(mrb_state *mrb, mrb_value self)
   196  {
   197    if (!mrb_block_given_p(mrb)) {
   198      const char *s;
   199      mrb_int len;
   200      const char *file = NULL;
   201      mrb_int line = 1;
   202      struct RProc *proc;
   203
   204      mrb_get_args(mrb, "s|zi", &s, &len, &file, &line);
   205      proc = create_proc_from_string(mrb, s, len, mrb_nil_value(), file, line);
   206      MRB_PROC_SET_TARGET_CLASS(proc, mrb_class_ptr(self));
   207      mrb_assert(!MRB_PROC_CFUNC_P(proc));
   208      mrb_vm_ci_target_class_set(mrb->c->ci, mrb_class_ptr(self));
   209      return exec_irep(mrb, self, proc);
   210    }
   211    else {
   212      mrb_get_args(mrb, "");
   213      return mrb_mod_module_eval(mrb, self);
   214    }
   215  }
   216
   217  void
   218  mrb_mruby_eval_gem_init(mrb_state* mrb)
   219  {
   220    mrb_define_module_function(mrb, mrb->kernel_module, "eval", f_eval, MRB_ARGS_ARG(1, 3));
   221    mrb_define_method_id(mrb, mrb_class_get_id(mrb, MRB_SYM(BasicObject)), MRB_SYM(instance_eval), f_instance_eval, MRB_ARGS_OPT(3)|MRB_ARGS_BLOCK());
   222    mrb_define_method_id(mrb, mrb_class_get_id(mrb, MRB_SYM(Module)), MRB_SYM(module_eval), f_class_eval, MRB_ARGS_OPT(3)|MRB_ARGS_BLOCK());
   223    mrb_define_method_id(mrb, mrb_class_get_id(mrb, MRB_SYM(Module)), MRB_SYM(class_eval), f_class_eval, MRB_ARGS_OPT(3)|MRB_ARGS_BLOCK());
   224  }
   225
   226  void
   227  mrb_mruby_eval_gem_final(mrb_state* mrb)
   228  {
   229  }
